#include "resource.h"
static int token(const char **s,char *out,size_t cap){size_t n=0;while(**s==' ')++*s;while(**s&&**s!=' '){unsigned char c=**s;if(c<33||c>126||n+1>=cap)return 0;out[n++]=c;++*s;}out[n]=0;return n!=0;}
static int prefix(const char *s,const char *p){while(*p)if(*s++!=*p++)return 0;return 1;}
static int path_valid(const char *s,int absolute){if(absolute){if(*s!='/')return 0;++s;}else if(*s=='/')return 0;unsigned depth=0;while(*s){const char *start=s;size_t len=0;while(*s&&*s!='/'){unsigned char c=*s++;if(c<33||c>126||c=='\\'||c==':'||++len>31)return 0;}if(!len||++depth>8||(len==1&&start[0]=='.')||(len==2&&start[0]=='.'&&start[1]=='.'))return 0;if(*s=='/'&&! *++s)return 0;}return depth!=0;}
int resource_parse(const char *s,struct resource_request *out){if(!out)return 0;*out=(struct resource_request){0};if(!s)return 0;struct resource_request a={0};char src[132];if(!token(&s,a.app,sizeof a.app)||!path_valid(a.app,1)||!token(&s,src,sizeof src))return 0;while(*s==' ')++s;if(*s)return 0;const char *p=src+4;if(prefix(src,"ram:"))a.ram=1;else if(!prefix(src,"ext:"))return 0;if(!path_valid(p,!a.ram))return 0;size_t n=0;while(p[n]){if(n+1>=sizeof a.path)return 0;a.path[n]=p[n];n++;}*out=a;return 1;}
void resource_clear(struct resource_snapshot *s){if(s){volatile unsigned char *p=(volatile unsigned char*)s;for(size_t i=0;i<sizeof *s;i++)p[i]=0;}}
int resource_prepare(const struct resource_request *r,const struct ramfs *ram,const struct ext4 *ext,struct resource_snapshot *out){if(!out)return 0;resource_clear(out);if(!r||r->ram>1||!path_valid(r->path,!r->ram))return 0;size_t n=0;if(r->ram){if(!ram||ramfs_read(ram,r->path,out->bytes,sizeof out->bytes,&n)!=RAMFS_OK){resource_clear(out);return 0;}}else{struct fs_inode i;if(!ext||!ext4_lookup(ext,r->path,&i)||(i.mode&0xf000)!=0x8000||i.size>sizeof out->bytes||!ext4_read(ext,&i,0,out->bytes,i.size)){resource_clear(out);return 0;}n=i.size;}out->length=n;return 1;}
